import { useReducer } from "react";

// @ts-ignore
export default function ErrorAlert({ status, children }) {
	// const initialState = {
	// 		status: "ready",
	// 		errorMessage: "",
	// 	};

	// 	const [{ status, errorMessage }, dispatch] = useReducer(
	// 		reducer,
	// 		initialState
	// 	);

	const x = 10;
	// @ts-ignore
	function reducer(state, action) {
		switch (action.type) {
			// case "allGood!":
			// 	return {
			// 		...state,
			// 		status: "ready",
			// 	};
			case "errorAddingTeam":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			case "errorNoTeamToAdd":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			case "errorSelectHomeTeam":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			case "errorSelectAwayTeam":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			case "errorSelectBothTeams":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			case "errorDifferentTeams":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};

			case "errorNegativeScore":
				return {
					...state,
					status: "error",
					errorMessage: action.payload,
				};
			default:
				throw new Error("reducer failed error.");
		}
	}

	return (
		<div className={status === "error" ? "error" : "hideError"}>
			<p>{children}</p>
		</div>
	);
}
